/**
 * StartScreen - UI component for starting the AR experience
 * Part of Phase 2: Camera Implementation
 */

export interface StartScreenOptions {
  title?: string;
  description?: string;
  buildCommit?: string;
  alternateHref?: string;
  alternateText?: string;
  buttonText?: string;
  onStart?: () => void | Promise<void>;
}

export class StartScreen {
  private container: HTMLElement;
  private titleElement: HTMLElement;
  private buttonElement: HTMLButtonElement;
  private statusElement: HTMLElement;
  private options: StartScreenOptions;

  constructor(options: StartScreenOptions = {}) {
    this.options = {
      title: 'COIN HUNT',
      buttonText: 'START AR',
      ...options,
    };

    this.container = document.createElement('div');
    this.container.style.position = 'fixed';
    this.container.style.top = '0';
    this.container.style.left = '0';
    this.container.style.width = '100vw';
    this.container.style.height = '100%';
    this.container.style.display = 'flex';
    this.container.style.flexDirection = 'column';
    this.container.style.alignItems = 'center';
    this.container.style.justifyContent = 'center';
    this.container.style.backgroundColor = 'rgba(0, 0, 0, 0.8)';
    this.container.style.zIndex = '1000';
    this.container.style.color = 'white';
    this.container.style.fontFamily = 'Arial, sans-serif';
    // iOS polish: respect notches/home indicator, avoid double-tap zoom,
    // remove the grey tap highlight on touch.
    this.container.style.paddingTop = 'env(safe-area-inset-top, 0px)';
    this.container.style.paddingLeft = 'env(safe-area-inset-left, 0px)';
    this.container.style.paddingRight = 'env(safe-area-inset-right, 0px)';
    this.container.style.paddingBottom = 'env(safe-area-inset-bottom, 0px)';
    this.container.style.boxSizing = 'border-box';
    this.container.style.touchAction = 'manipulation';
    this.container.style.setProperty('-webkit-tap-highlight-color', 'transparent');

    // Title
    this.titleElement = document.createElement('h1');
    this.titleElement.textContent = this.options.title ?? 'COIN HUNT';
    this.titleElement.style.fontSize = '2.5rem';
    this.titleElement.style.marginBottom = '2rem';
    this.titleElement.style.textAlign = 'center';

    // Button
    this.buttonElement = document.createElement('button');
    this.buttonElement.textContent = this.options.buttonText ?? 'START AR';
    this.buttonElement.style.padding = '1rem 2rem';
    this.buttonElement.style.fontSize = '1.2rem';
    this.buttonElement.style.backgroundColor = '#4CAF50';
    this.buttonElement.style.color = 'white';
    this.buttonElement.style.border = 'none';
    this.buttonElement.style.borderRadius = '5px';
    this.buttonElement.style.cursor = 'pointer';
    this.buttonElement.style.transition = 'background-color 0.3s';
    // iOS polish: 44px minimum touch target, no double-tap zoom delay,
    // no grey tap highlight.
    this.buttonElement.style.minWidth = '44px';
    this.buttonElement.style.minHeight = '44px';
    this.buttonElement.style.touchAction = 'manipulation';
    this.buttonElement.style.setProperty('-webkit-tap-highlight-color', 'transparent');

    this.buttonElement.addEventListener('mouseenter', () => {
      this.buttonElement.style.backgroundColor = '#45a049';
    });

    this.buttonElement.addEventListener('mouseleave', () => {
      this.buttonElement.style.backgroundColor = '#4CAF50';
    });

    this.buttonElement.addEventListener('click', async () => {
      this.setStatus('Requesting camera permission...');
      try {
        if (this.options.onStart) {
          await this.options.onStart();
        }
      } catch (error) {
        this.setStatus(`Error: ${(error as Error).message}`);
      }
    });

    // Status
    this.statusElement = document.createElement('div');
    this.statusElement.style.marginTop = '1rem';
    this.statusElement.style.fontSize = '0.9rem';
    this.statusElement.style.color = '#ccc';
    this.statusElement.style.textAlign = 'center';

    // Assemble
    this.container.appendChild(this.titleElement);
    const description = document.createElement('p');
    description.textContent = options.description ?? '';
    description.style.cssText = 'text-align: center; max-width: 320px; padding: 0 16px';
    this.container.appendChild(description);
    this.container.appendChild(this.buttonElement);
    if (options.alternateHref) {
      const alternate = document.createElement('a');
      alternate.href = options.alternateHref;
      alternate.textContent = options.alternateText ?? 'Desktop demo';
      alternate.style.cssText =
        'color: white; padding: 16px; min-height: 44px; box-sizing: border-box';
      this.container.appendChild(alternate);
    }
    if (options.buildCommit) {
      const build = document.createElement('small');
      build.textContent = `Build ${options.buildCommit}`;
      this.container.appendChild(build);
    }
    this.container.appendChild(this.statusElement);

    document.body.appendChild(this.container);
  }

  /**
   * Update the status message
   */
  setStatus(message: string): void {
    this.statusElement.textContent = message;
  }

  /**
   * Hide the start screen
   */
  hide(): void {
    this.container.style.display = 'none';
  }

  /**
   * Show the start screen
   */
  show(): void {
    this.container.style.display = 'flex';
  }

  /**
   * Check if the start screen is visible
   */
  isVisible(): boolean {
    return this.container.style.display !== 'none';
  }

  /**
   * Remove the start screen from DOM
   */
  destroy(): void {
    if (this.container.parentNode) {
      this.container.parentNode.removeChild(this.container);
    }
  }

  /**
   * Update button text
   */
  setButtonText(text: string): void {
    this.buttonElement.textContent = text;
  }

  /**
   * Enable or disable the button
   */
  setButtonEnabled(enabled: boolean): void {
    this.buttonElement.disabled = !enabled;
    this.buttonElement.style.opacity = enabled ? '1' : '0.5';
    this.buttonElement.style.cursor = enabled ? 'pointer' : 'not-allowed';
  }
}
