/** Coordinates the camera, tracking, rendering demo and injected providers.
 * Real WebGL is used in the browser; jsdom wiring tests use renderer stubs.
 */

import { CameraSource, cameraSource } from '../tracking/CameraSource';
import type { TrackingProvider, CameraPose } from '../tracking/TrackingProvider';
import { SimulationTrackingProvider } from '../tracking/SimulationTrackingProvider';
import { AlvaTrackingProvider, alvaVerticalFieldOfView } from '../tracking/AlvaTrackingProvider';
import { CameraBackground } from '../rendering/CameraBackground';
import { WorldPlacementMarker } from '../rendering/WorldPlacementMarker';
import { StartScreen } from '../ui/StartScreen';
import { HUD } from '../ui/HUD';
import { TrackingStatus } from '../ui/TrackingStatus';
import { Game } from '../game/Game';
import type {
  GameBeacon,
  GameCoin,
  GameHUD,
  GamePlayer,
  GameStatus,
  GameWorld,
} from '../game/Game';
import { Player } from '../game/Player';
import { Coin } from '../game/Coin';
import { Beacon } from '../game/Beacon';
import { ARWorld } from '../rendering/ARWorld';
import { SoundPlayer } from '../utils/sound';
import { TrackingMetrics } from '../utils/trackingMetrics';
import * as THREE from 'three';

/** Minimal camera surface App needs (real CameraSource or a test fake). */
export interface AppCameraSource {
  start(): Promise<unknown>;
  stop(): void;
  getVideoElement(): HTMLVideoElement;
  isStreaming(): boolean;
}

/** GameCoin plus the optional visual tick the real Coin provides. */
export interface AppCoin extends GameCoin {
  update?(dtSec: number, elapsedSec: number): void;
  dispose?(): void;
}

/** GameBeacon plus the optional visual tick the real Beacon provides. */
export interface AppBeacon extends GameBeacon {
  update?(dtSec: number, elapsedSec: number): void;
  dispose?(): void;
}

/** GameHUD plus the optional DOM handle the real HUD provides. */
export interface AppHud extends GameHUD {
  element?: HTMLElement;
  destroy?(): void;
}

/** GameStatus plus the optional DOM handle the real TrackingStatus provides. */
export interface AppStatus extends GameStatus {
  element?: HTMLElement;
  destroy?(): void;
}

/** Minimal sound surface (real SoundPlayer or a test fake). */
export interface AppSound {
  playCollect(): Promise<unknown>;
}

/** Minimal metrics surface (real TrackingMetrics or a test fake). */
export interface AppMetrics {
  startSession(): void;
  recordFrame(pose: CameraPose | null, atMs?: number): void;
}

/** Minimal game surface (real Game or a test fake). */
export interface AppGame {
  start(): Promise<void>;
  requestCameraAndTracking(): Promise<void>;
  update(dtSec?: number): void;
  restart?(): void;
  dispose?(): void;
}

export interface AppOptions {
  canvas?: HTMLCanvasElement;
  cameraEnabled?: boolean;
  buildCommit?: string;
  cameraOptions?: ConstructorParameters<typeof CameraSource>[0];
  cameraSource?: AppCameraSource;
  tracking?: TrackingProvider;
  player?: GamePlayer;
  coin?: AppCoin;
  beacon?: AppBeacon;
  world?: GameWorld;
  hud?: AppHud;
  status?: AppStatus;
  sound?: AppSound;
  metrics?: AppMetrics;
  game?: AppGame;
}

function isTestEnv(): boolean {
  try {
    const g = globalThis as unknown as Record<string, unknown>;
    const proc = g['process'] as { env?: Record<string, unknown> } | undefined;
    return !!proc?.env?.['JEST_WORKER_ID'];
  } catch {
    return false;
  }
}

export class App {
  private cameraSource: AppCameraSource;
  private startScreen: StartScreen;
  private scene!: THREE.Scene;
  private camera!: THREE.PerspectiveCamera;
  private renderer!: THREE.WebGLRenderer;
  private background: CameraBackground | null = null;
  private readonly cameraEnabled: boolean;
  private readonly simulated: boolean;
  private readonly worldPlacementMode: boolean;
  private readonly trackingSize: { width: number; height: number };
  private worldPlacementMarker: WorldPlacementMarker | null = null;
  private trackingGuide: HTMLElement | null = null;
  private rendererError: Error | null = null;
  private animationFrameId = 0;

  private tracking: TrackingProvider;
  private player: GamePlayer;
  private coin: AppCoin;
  private beacon: AppBeacon;
  private world: GameWorld;
  private hud: AppHud;
  private status: AppStatus;
  private sound: AppSound;
  private metrics: AppMetrics;
  private game: AppGame;

  private starting = false;
  private started = false;
  private wasPlayingOnHide = false;
  private lastFrameMs = 0;
  private elapsedSec = 0;
  private trackingUnsubscribe: (() => void) | null = null;

  private readonly handleResize = (): void => {
    this.onResize();
  };

  private readonly handleOrientationChange = (): void => {
    this.onResize();
  };

  private readonly handleVisibilityChange = (): void => {
    if (typeof document === 'undefined') {
      return;
    }
    if (document.hidden) {
      this.wasPlayingOnHide = this.started && this.animationFrameId !== 0;
      this.stopAnimation();
    } else if (this.wasPlayingOnHide && this.started) {
      this.wasPlayingOnHide = false;
      this.lastFrameMs = performance.now();
      this.startAnimation();
    }
  };

  constructor(options: AppOptions = {}) {
    this.cameraEnabled = options.cameraEnabled ?? true;
    this.worldPlacementMode = options.tracking === undefined && this.cameraEnabled;
    this.trackingSize = this.getInitialTrackingSize();
    this.cameraSource = options.cameraSource
      ? options.cameraSource
      : options.cameraOptions
        ? new CameraSource(options.cameraOptions)
        : cameraSource;

    // Initialize Three.js (stubs under Jest where WebGL is unavailable).
    this.initThreeJS(options.canvas);

    this.tracking =
      options.tracking ??
      (this.cameraEnabled
        ? new AlvaTrackingProvider(() => this.cameraSource.getVideoElement(), {
            trackingWidth: this.trackingSize.width,
            trackingHeight: this.trackingSize.height,
            fieldOfView: 45,
            targetFps: 30,
          })
        : new SimulationTrackingProvider());
    this.simulated = this.tracking instanceof SimulationTrackingProvider;
    this.player = options.player ?? new Player();
    this.world = options.world ?? new ARWorld();
    if (this.worldPlacementMode && this.world instanceof ARWorld && !isTestEnv()) {
      this.worldPlacementMarker = new WorldPlacementMarker(this.scene, this.world);
      this.trackingGuide = this.createTrackingGuide();
    }
    this.coin = options.coin ?? new Coin(this.scene, { glbUrl: null });
    this.beacon = options.beacon ?? new Beacon(this.scene);
    this.hud =
      options.hud ??
      new HUD(undefined, { onRestart: () => this.game.restart?.(), simulated: this.simulated });
    this.status =
      options.status ??
      new TrackingStatus(undefined, {
        simulated: this.simulated,
        buildCommit: options.buildCommit,
      });
    this.sound = options.sound ?? new SoundPlayer(this.resolveBaseUrl());
    this.metrics = options.metrics ?? new TrackingMetrics();
    this.game =
      options.game ??
      new Game({
        tracking: this.tracking,
        player: this.player,
        coin: this.coin,
        beacon: this.beacon,
        world: this.world,
        hud: this.hud,
        status: this.status,
        sound: this.sound,
      });

    // Overlays stay hidden behind the start screen until AR starts.
    this.setOverlaysVisible(false);

    // Initialize UI
    this.startScreen = new StartScreen({
      onStart: () => this.startAR(),
      buttonText: this.cameraEnabled ? 'START AR PLACEMENT' : 'START DESKTOP DEMO',
      description: this.simulated
        ? 'Simulated position — room tracking is not connected.'
        : 'AlvaAR world placement — move slowly until the target appears.',
      buildCommit: options.buildCommit,
      alternateHref: this.cameraEnabled ? '?demo=1' : '?',
      alternateText: this.cameraEnabled ? 'Try without a camera' : 'Use the camera instead',
    });

    // Handle window resize / orientation and backgrounding (Phase 11).
    window.addEventListener('resize', this.handleResize);
    window.addEventListener('orientationchange', this.handleOrientationChange);
    document.addEventListener('visibilitychange', this.handleVisibilityChange);
  }

  /**
   * Whether the AR session is currently running.
   */
  isRunning(): boolean {
    return this.started;
  }

  /**
   * Initialize Three.js scene, camera, and renderer.
   * Under Jest (no WebGL) fall back to no-op stubs so imports stay side-effect free.
   */
  private initThreeJS(canvas?: HTMLCanvasElement): void {
    if (isTestEnv()) {
      this.scene = this.createStubScene();
      this.camera = this.createStubCamera();
      this.renderer = this.createStubRenderer();
      return;
    }
    try {
      // Scene
      this.scene = new THREE.Scene();
      this.scene.background = null;

      // Camera
      const aspect = window.innerWidth / window.innerHeight;
      const fieldOfView = this.worldPlacementMode
        ? alvaVerticalFieldOfView(this.trackingSize.width, this.trackingSize.height, 45)
        : 75;
      this.camera = new THREE.PerspectiveCamera(fieldOfView, aspect, 0.1, 1000);
      this.camera.position.set(0, 0, 5);

      // Renderer
      const rendererOpts: THREE.WebGLRendererParameters = canvas
        ? { antialias: true, alpha: true, canvas }
        : { antialias: true, alpha: true };
      this.renderer = new THREE.WebGLRenderer(rendererOpts);
      this.renderer.setSize(window.innerWidth, window.innerHeight);
      this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
      this.renderer.setClearColor(0x000000, 0);
      this.renderer.domElement.dataset.testid = 'ar-canvas';
      Object.assign(this.renderer.domElement.style, { position: 'fixed', inset: '0', zIndex: '1' });
      document.body.appendChild(this.renderer.domElement);

      // Add ambient light
      const ambientLight = new THREE.AmbientLight(0xffffff, 0.5);
      this.scene.add(ambientLight);

      // Add directional light
      const directionalLight = new THREE.DirectionalLight(0xffffff, 0.8);
      directionalLight.position.set(5, 10, 7);
      this.scene.add(directionalLight);
    } catch {
      this.rendererError = new Error(
        'WebGL is unavailable. Enable hardware acceleration or try another browser.'
      );
      // Keep the start screen usable so it can explain the rendering failure.
      this.scene = this.createStubScene();
      this.camera = this.createStubCamera();
      this.renderer = this.createStubRenderer();
    }
  }

  private createStubScene(): THREE.Scene {
    const scene = {
      background: null,
      add: (): void => undefined,
      remove: (): void => undefined,
    };
    return scene as unknown as THREE.Scene;
  }

  private createStubCamera(): THREE.PerspectiveCamera {
    const position = {
      x: 0,
      y: 0,
      z: 5,
      set: (x: number, y: number, z: number): void => {
        position.x = x;
        position.y = y;
        position.z = z;
      },
    };
    const quaternion = {
      x: 0,
      y: 0,
      z: 0,
      w: 1,
      set: (x: number, y: number, z: number, w: number): void => {
        quaternion.x = x;
        quaternion.y = y;
        quaternion.z = z;
        quaternion.w = w;
      },
    };
    const camera = {
      aspect: 1,
      position,
      quaternion,
      updateProjectionMatrix: (): void => undefined,
    };
    return camera as unknown as THREE.PerspectiveCamera;
  }

  private createStubRenderer(): THREE.WebGLRenderer {
    const canvas = document.createElement('canvas');
    const renderer = {
      domElement: canvas,
      setSize: (): void => undefined,
      setPixelRatio: (): void => undefined,
      render: (): void => undefined,
      dispose: (): void => undefined,
    };
    document.body.appendChild(canvas);
    return renderer as unknown as THREE.WebGLRenderer;
  }

  /**
   * Base URL for runtime assets (sounds). Derived from document.baseURI so
   * GitHub Pages sub-path builds resolve, without referencing import.meta
   * (which would break ts-jest CommonJS execution).
   */
  private resolveBaseUrl(): string {
    try {
      if (typeof document !== 'undefined' && typeof document.baseURI === 'string') {
        return new URL('.', document.baseURI).pathname;
      }
    } catch {
      // Fall through to the root default.
    }
    return '/';
  }

  private getInitialTrackingSize(): { width: number; height: number } {
    const aspect = window.innerWidth / window.innerHeight;
    const even = (value: number): number => Math.max(2, Math.round(value / 2) * 2);
    return aspect >= 1
      ? { width: 640, height: even(640 / aspect) }
      : { width: even(640 * aspect), height: 640 };
  }

  private createTrackingGuide(): HTMLElement {
    const guide = document.createElement('div');
    guide.dataset.testid = 'tracking-guide';
    guide.style.cssText =
      'position:fixed;top:calc(env(safe-area-inset-top, 0px) + 12px);left:50%;' +
      'transform:translateX(-50%);z-index:500;max-width:min(88vw,520px);padding:10px 14px;' +
      'border-radius:10px;background:rgba(0,0,0,.65);color:white;text-align:center;' +
      'font:600 14px/1.35 Arial,sans-serif;pointer-events:none;display:none';
    guide.textContent = 'Move your phone slowly and point at detailed, well-lit surfaces.';
    document.body.appendChild(guide);
    return guide;
  }

  private updateTrackingGuide(state: string): void {
    if (this.trackingGuide === null) return;
    if (state === 'ACTIVE') {
      this.trackingGuide.textContent =
        'Target placed 2.5 m ahead — move sideways and check that it stays fixed.';
    } else if (state === 'LOST') {
      this.trackingGuide.textContent = 'Tracking lost — return to the last view and move slowly.';
    } else {
      this.trackingGuide.textContent =
        'Move your phone slowly and point at detailed, well-lit surfaces.';
    }
  }

  /**
   * Start the full AR session: camera -> tracking -> game.
   * Guarded against double-tap; failures surface on the StartScreen.
   */
  async startAR(): Promise<void> {
    if (this.starting || this.started) {
      return;
    }
    this.starting = true;
    try {
      if (this.rendererError) throw this.rendererError;
      this.startScreen.setStatus(this.cameraEnabled ? 'Starting camera...' : 'Starting demo...');
      this.startScreen.setButtonEnabled(false);

      if (this.cameraEnabled) {
        await this.cameraSource.start();
        this.background = new CameraBackground(this.cameraSource.getVideoElement());
      }

      // Start tracking, then drive the game through READY -> PLAYING.
      this.startScreen.setStatus('Starting tracking...');
      await this.tracking.start();
      await this.game.start();
      await this.game.requestCameraAndTracking();

      this.metrics.startSession();
      if (this.trackingUnsubscribe) {
        this.trackingUnsubscribe();
      }
      this.trackingUnsubscribe = this.tracking.onStateChange((s) => {
        this.status.setTracking(s);
        this.updateTrackingGuide(s);
      });
      this.status.setTracking(this.tracking.getState());
      this.updateTrackingGuide(this.tracking.getState());

      // Hide start screen, reveal HUD/status, start the loop.
      this.startScreen.hide();
      this.setOverlaysVisible(true);
      this.started = true;
      this.startAnimation();

      this.startScreen.setStatus(
        this.simulated ? 'Simulation active' : 'AlvaAR ready — move slowly to initialize'
      );
    } catch (error) {
      this.stopCamera();
      const message = error instanceof Error ? error.message : 'Unknown error';
      this.startScreen.setStatus(`AR start failed: ${message}`);
      this.startScreen.setButtonEnabled(true);
    } finally {
      this.starting = false;
    }
  }

  /**
   * Stop the camera and tear down the running session (keeps DOM for restart).
   */
  stopCamera(): void {
    this.started = false;
    this.starting = false;
    this.wasPlayingOnHide = false;

    // Stop animation
    this.stopAnimation();

    // Stop tracking
    this.tracking.stop();
    if (this.trackingUnsubscribe) {
      this.trackingUnsubscribe();
      this.trackingUnsubscribe = null;
    }

    this.cameraSource.stop();

    this.background?.hide();
    this.background = null;
    this.worldPlacementMarker?.reset();

    // Hide overlays
    this.setOverlaysVisible(false);

    // Show start screen
    this.startScreen.show();
    this.startScreen.setStatus('Camera stopped');
    this.startScreen.setButtonEnabled(true);
  }

  /**
   * Start the animation loop
   */
  private startAnimation(): void {
    this.stopAnimation();
    this.lastFrameMs = performance.now();
    this.animate();
  }

  /**
   * Animation loop: video feed + tracking pose -> camera + game visuals.
   * Never throws: a single bad frame must not kill the rAF loop.
   */
  private animate(): void {
    this.animationFrameId = requestAnimationFrame(() => this.animate());

    const now = performance.now();
    const dt = this.lastFrameMs > 0 ? Math.min((now - this.lastFrameMs) / 1000, 0.5) : 1 / 60;
    this.lastFrameMs = now;
    this.elapsedSec += dt;

    try {
      const pose = this.tracking.getPose();
      if (pose) {
        this.applyPoseToCamera(pose);
        this.worldPlacementMarker?.placeFromFirstPose(pose);
      }
      const trackingState = this.tracking.getState();
      this.worldPlacementMarker?.setTrackingVisible(trackingState === 'ACTIVE');
      this.status.setTracking(trackingState, this.buildTrackingInfo(pose));
      if (!this.worldPlacementMode) {
        this.coin.update?.(dt, this.elapsedSec);
        this.beacon.update?.(dt, this.elapsedSec);
        this.game.update(dt);
      }
      this.metrics.recordFrame(pose);
    } catch {
      // Swallow per-frame errors to keep the loop alive.
    }

    this.renderer.render(this.scene, this.camera);
  }

  private applyPoseToCamera(pose: CameraPose): void {
    this.camera.position.set(pose.position.x, pose.position.y, pose.position.z);
    this.camera.quaternion.set(
      pose.quaternion.x,
      pose.quaternion.y,
      pose.quaternion.z,
      pose.quaternion.w
    );
  }

  private buildTrackingInfo(pose: CameraPose | null): {
    fps?: number;
    featureCount?: number;
    position?: { x: number; y: number; z: number };
  } {
    const info: {
      fps?: number;
      featureCount?: number;
      position?: { x: number; y: number; z: number };
    } = {};
    const t = this.tracking as unknown as {
      getFps?: () => number;
      getFeatureCount?: () => number;
    };
    try {
      if (typeof t.getFps === 'function') {
        const fps = t.getFps();
        if (typeof fps === 'number' && Number.isFinite(fps)) {
          info.fps = fps;
        }
      }
      if (typeof t.getFeatureCount === 'function') {
        const featureCount = t.getFeatureCount();
        if (typeof featureCount === 'number' && Number.isFinite(featureCount)) {
          info.featureCount = featureCount;
        }
      }
    } catch {
      // Optional provider stats must never break the frame.
    }
    if (pose) {
      info.position = { x: pose.position.x, y: pose.position.y, z: pose.position.z };
    }
    return info;
  }

  private setOverlaysVisible(visible: boolean): void {
    const display = visible ? 'flex' : 'none';
    if (this.hud.element) {
      this.hud.element.style.display = visible && !this.worldPlacementMode ? 'flex' : 'none';
    }
    if (this.status.element) {
      this.status.element.style.display = display;
    }
    if (this.trackingGuide) {
      this.trackingGuide.style.display = visible && this.worldPlacementMode ? 'block' : 'none';
    }
  }

  /**
   * Stop the animation loop
   */
  private stopAnimation(): void {
    if (this.animationFrameId) {
      cancelAnimationFrame(this.animationFrameId);
      this.animationFrameId = 0;
    }
  }

  /**
   * Handle window resize / orientation change.
   */
  private onResize(): void {
    const width = window.innerWidth;
    const height = window.innerHeight;

    this.camera.aspect = width / height;
    this.camera.updateProjectionMatrix();

    this.renderer.setSize(width, height);
  }

  /**
   * Clean up all resources
   */
  destroy(): void {
    window.removeEventListener('resize', this.handleResize);
    window.removeEventListener('orientationchange', this.handleOrientationChange);
    document.removeEventListener('visibilitychange', this.handleVisibilityChange);

    this.stopCamera();
    this.stopAnimation();

    try {
      this.game.dispose?.();
    } catch {
      // Ignore teardown failures.
    }
    try {
      this.coin.dispose?.();
    } catch {
      // Ignore teardown failures.
    }
    try {
      this.beacon.dispose?.();
    } catch {
      // Ignore teardown failures.
    }
    this.worldPlacementMarker?.dispose();
    this.worldPlacementMarker = null;
    this.trackingGuide?.remove();
    this.trackingGuide = null;

    // Clean up Three.js
    this.renderer.dispose();
    if (this.renderer.domElement.parentNode) {
      this.renderer.domElement.parentNode.removeChild(this.renderer.domElement);
    }

    // Clean up UI
    this.hud.destroy?.();
    this.status.destroy?.();
    this.startScreen.destroy();
  }
}
